// InfoBar — Gtk.InfoBar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles infobar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { MessageType } from "@/lib/enums"

export interface InfoBarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** MessageType, from Gtk.InfoBar */
  messageType?: MessageType

  /** gboolean, from Gtk.InfoBar */
  revealed?: boolean

  /** gboolean, from Gtk.InfoBar */
  showCloseButton?: boolean
}

export function InfoBar({ className, children }: InfoBarProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
